-- =====================================================================
--  MODULE 2 · Bronze: store the raw records, untouched
-- =====================================================================
--  Bronze keeps exactly what the agents sent: one row per record, the JSON
--  as a string. Nothing is parsed, nothing is lost. If a parsing rule is
--  wrong in silver, we replay from here (module 7).
--  Here the records are generated by the simulator; in production they come
--  from the OpenTelemetry collector, Kafka or ClickPipes.
--
--  We load the day from 00:00 to 20:00 now. The evening (20:00 to 24:00)
--  will arrive in module 3, once the materialized views exist: it will show
--  the continuous flow.
-- =====================================================================


-- STEP 1 · The bronze table
--  ORDER BY (source, received_at): bronze is read by source and by time range.
--  ZSTD(3) on the payload: JSON logs are very repetitive (keys, pod names,
--  messages), they compress extremely well.
CREATE OR REPLACE TABLE payflow_raw.log_records
(
    received_at  DateTime64(3, 'UTC'),
    source       LowCardinality(String),       -- fluent-bit (container logs) or k8s-events
    payload      String CODEC(ZSTD(3))
)
ENGINE = MergeTree
PARTITION BY toDate(received_at)
ORDER BY (source, received_at);


-- STEP 2 · Load the day, from 00:00 to 20:00, in 4 batches
--  Each batch stays well under the 60 s limit of the SQL console.
--  Note: generating the records costs more than writing them. ClickHouse
--  writes several million rows per second on a single replica.
INSERT INTO payflow_raw.log_records SELECT * FROM payflow_sim.raw_records(from_s = 0, to_s = 21600);       -- 00:00 to 06:00
-- Measured: 4.7 s · 21,947 rows read (181.8 KB) · 1 M rows written · 1.3 GB memory
INSERT INTO payflow_raw.log_records SELECT * FROM payflow_sim.raw_records(from_s = 21600, to_s = 43200);   -- 06:00 to 12:00
-- Measured: 5.21 s · 21,947 rows read (181.8 KB) · 1.1 M rows written · 1.4 GB memory
INSERT INTO payflow_raw.log_records SELECT * FROM payflow_sim.raw_records(from_s = 43200, to_s = 57600);   -- 12:00 to 16:00
-- Measured: 6.18 s · 14,747 rows read (130.6 KB) · 1.5 M rows written · 1.7 GB memory
INSERT INTO payflow_raw.log_records SELECT * FROM payflow_sim.raw_records(from_s = 57600, to_s = 72000);   -- 16:00 to 20:00
-- Measured: 8.49 s · 14,747 rows read (125.6 KB) · 2.3 M rows written · 2 GB memory


-- STEP 3 · What did we store, and how small is it?
SELECT
    source,
    count()                                                         AS records,
    formatReadableSize(sum(length(payload)))                        AS raw_json
FROM payflow_raw.log_records
GROUP BY source;
-- Measured: 34 ms · 6 M rows read (51.5 MB) · 169.8 MB memory

SELECT
    formatReadableSize(sum(data_uncompressed_bytes))                AS uncompressed,
    formatReadableSize(sum(data_compressed_bytes))                  AS on_disk,
    round(sum(data_uncompressed_bytes) / sum(data_compressed_bytes), 1) AS ratio
FROM system.parts
WHERE database = 'payflow_raw' AND table = 'log_records' AND active;
-- Measured: 3 ms · 7 rows read
-- What to look for: the ratio. Logs are the best case for columnar compression.


-- STEP 4 · Checkpoint
SELECT
    if((SELECT count() FROM payflow_raw.log_records WHERE source = 'fluent-bit') > 5000000, 'OK', 'KO') AS container_logs,
    if((SELECT count() FROM payflow_raw.log_records WHERE source = 'k8s-events') > 300, 'OK', 'KO')     AS k8s_events,
    if((SELECT max(received_at) FROM payflow_raw.log_records) < toDateTime64('2026-11-27 20:00:05', 3, 'UTC'), 'OK', 'KO') AS stops_at_20h
SETTINGS select_sequential_consistency = 1;
-- Measured: 27 ms · 8,677 rows read (8.8 KB)
